        QCOMPARE(textNamed(root, u"review-order-tout-aquilon-line"_s),
                 u"5 séries · 5 étapes, dont 3 recopiées"_s);
        QVERIFY(shownNamed(root, u"review-order-tout-aquilon-badge"_s));
