        QVERIFY(reader);
        QQuickItem *view = nullptr;
        QTRY_VERIFY((view = itemNamed(window->contentItem(), u"reader-view"_s)));
        QTRY_VERIFY(!reader->loading() && reader->pageCount() == 190);
