        QCOMPARE(textNamed(panel, u"reader-volume-chapters"_s), u"98 à 101"_s);
        for (int i = 0; i < 4; ++i)
            QVERIFY(drawn(panel, u"reader-volume-chapter-%1"_s.arg(i)));
