        QVERIFY(view);
        auto *window = view->window();
        QQuickItem *sheet = itemNamed(view, u"reader-sheet"_s);
        QVERIFY(sheet);

        QTest::keyClick(window, Qt::Key_Plus, Qt::ControlModifier);
        QTest::keyClick(window, Qt::Key_Plus, Qt::ControlModifier);
