        QVERIFY(laidOut(window));
        clickOn(window, itemNamed(dialog, u"code-back"_s));
        QTRY_VERIFY(shownNamed(dialog, u"code-rounds"_s));
        QVERIFY(hiddenNamed(dialog, u"code-command"_s));
